/usr/bin/zsh -lc "python3 -B - <<'PY'
from client import save

class RecordingTransport:
    def __init__(self):
        self.requests = []
    def put(self, path, body):
        self.requests.append((path, body))
        return {'ok': True}

cases = [
    ('Ada', 'Ada'),
    ('  Ada  ', 'Ada'),
    ('Ada Lovelace', 'Ada Lovelace'),
    ('', ''),
    (' \\t\\n ', ''),
    ('\\u2003Ada\\u00a0', 'Ada'),
]
for supplied, expected in cases:
    transport = RecordingTransport()
    assert save(transport, supplied) == {'ok': True}
    assert transport.requests == [('/settings', {'display_name': expected})]
    print(f'{supplied"'!r} -> {expected!r}: request verified'"')

class FailingTransport:
    def put(self, path, body):
        raise ConnectionError('simulated transport failure')

try:
    save(FailingTransport(), ' Ada ')
except ConnectionError:
    print('Transport failure propagates to caller: verified')
else:
    raise AssertionError('Transport failure was swallowed')
PY

